<?php
namespace Delnavazan\Platform\Admin\Controller;
use Delnavazan\Platform\Core\Application\{StudentIdentityResolutionService,StudentAcceptanceAuthorityService,StudentAcceptanceAuthorityReadService};
use Delnavazan\Platform\Core\Infrastructure\Repository\StudentIdentityAuthorityRepository;

/** Protected internal review surface. It deliberately offers no automatic matching, document upload, or public workflow. */
final class StudentIdentityAuthorityController {
    private const IDENTITY=array('resolve_existing_student','create_and_resolve_student','record_identity_outcome');
    private const AUTHORITY=array('classify_student_capacity','establish_student_principal','revoke_student_principal','supersede_student_principal','grant_guardian_authority','revoke_guardian_authority','supersede_guardian_authority');
    public static function handlePost():void{if(($_SERVER['REQUEST_METHOD']??'')!=='POST')return;$post=wp_unslash($_POST);$action=sanitize_key($post['dzn_action']??'');if(!in_array($action,array_merge(self::IDENTITY,self::AUTHORITY,array('assess_acceptance_eligibility')),true))return;$cap=in_array($action,self::IDENTITY,true)?'dzn_resolve_booking_request_student_identity':(in_array($action,self::AUTHORITY,true)?'dzn_manage_student_acceptance_authority':'dzn_view_student_acceptance_eligibility');if(!current_user_can($cap))wp_die('Access denied.','Delnavazan',array('response'=>403));check_admin_referer('dzn_platform_'.$action);try{$actor=get_current_user_id();$identity=new StudentIdentityResolutionService();$authority=new StudentAcceptanceAuthorityService();$result=match($action){'resolve_existing_student'=>$identity->resolveExisting((int)$post['booking_request_id'],(int)$post['student_id'],self::text($post,'verification_basis'),self::text($post,'evidence_channel'),self::text($post,'evidence_at'),$actor),'create_and_resolve_student'=>$identity->createAndResolve((int)$post['booking_request_id'],array('display_name'=>self::text($post,'display_name')),self::text($post,'verification_basis'),self::text($post,'evidence_channel'),self::text($post,'evidence_at'),$actor),'record_identity_outcome'=>$identity->recordOutcome((int)$post['booking_request_id'],self::text($post,'outcome'),self::text($post,'verification_basis'),self::text($post,'evidence_channel'),self::text($post,'evidence_at'),$actor),'classify_student_capacity'=>$authority->classify((int)$post['student_id'],self::text($post,'classification'),self::text($post,'verification_basis'),self::text($post,'evidence_channel'),self::text($post,'evidence_at'),$actor),'establish_student_principal'=>$authority->establishPrincipal((int)$post['student_id'],(int)$post['wordpress_user_id'],self::text($post,'verification_basis'),self::text($post,'evidence_channel'),self::text($post,'evidence_at'),$actor),'revoke_student_principal'=>(function()use($authority,$post,$actor){$authority->revokePrincipal((int)$post['link_id'],(int)$post['version'],self::text($post,'reason_code'),$actor);return 0;})(),'supersede_student_principal'=>$authority->supersedePrincipal((int)$post['link_id'],(int)$post['version'],(int)$post['wordpress_user_id'],self::text($post,'verification_basis'),self::text($post,'evidence_channel'),self::text($post,'evidence_at'),self::text($post,'reason_code'),$actor),'grant_guardian_authority'=>$authority->grantGuardian((int)$post['student_id'],(int)$post['wordpress_user_id'],self::text($post,'verification_basis'),self::text($post,'evidence_channel'),self::text($post,'evidence_at'),self::optional($post,'effective_until'),$actor),'revoke_guardian_authority'=>(function()use($authority,$post,$actor){$authority->revokeGuardian((int)$post['grant_id'],(int)$post['version'],self::text($post,'reason_code'),$actor);return 0;})(),'supersede_guardian_authority'=>$authority->supersedeGuardian((int)$post['grant_id'],(int)$post['version'],(int)$post['wordpress_user_id'],self::text($post,'verification_basis'),self::text($post,'evidence_channel'),self::text($post,'evidence_at'),self::optional($post,'effective_until'),self::text($post,'reason_code'),$actor),'assess_acceptance_eligibility'=>(new StudentAcceptanceAuthorityReadService())->assess((int)$post['booking_request_id'],(int)$post['wordpress_user_id'])};self::redirect(is_array($result)?'Eligibility: '.wp_json_encode($result):'Saved #'.$result);}catch(\Throwable){self::redirect('Operation failed; no change was saved.',true);}}
    public static function screen():void{if(!current_user_can('dzn_view_student_acceptance_eligibility')){echo '<div class="wrap"><p>Access denied.</p></div>';return;}$repo=new StudentIdentityAuthorityRepository();echo '<div class="wrap"><h1>Student identity &amp; acceptance authority</h1><p>Human-reviewed internal records only. This surface cannot accept an arrangement, enrol a Student, upload documents, or match request contact data automatically.</p>';self::messages();if(current_user_can('dzn_resolve_booking_request_student_identity')){self::form('resolve_existing_student','Resolve Booking Request to existing Student',array('booking_request_id','student_id','verification_basis','evidence_channel','evidence_at'));self::form('create_and_resolve_student','Create a distinct Student and resolve',array('booking_request_id','display_name','verification_basis','evidence_channel','evidence_at'));self::form('record_identity_outcome','Record non-resolved review outcome',array('booking_request_id','outcome (unresolved, ambiguous, rejected)','verification_basis','evidence_channel','evidence_at'));}if(current_user_can('dzn_manage_student_acceptance_authority')){self::form('classify_student_capacity','Classify acceptance capacity',array('student_id','classification (adult, minor, unknown)','verification_basis','evidence_channel','evidence_at'));self::form('establish_student_principal','Establish Student principal link',array('student_id','wordpress_user_id','verification_basis','evidence_channel','evidence_at'));self::form('revoke_student_principal','Revoke Student principal link',array('link_id','version','reason_code'));self::form('supersede_student_principal','Atomically supersede Student principal link',array('link_id','version','wordpress_user_id','verification_basis','evidence_channel','evidence_at','reason_code'));self::form('grant_guardian_authority','Grant guardian representative authority',array('student_id','wordpress_user_id','verification_basis','evidence_channel','evidence_at','effective_until (optional)'));self::form('revoke_guardian_authority','Revoke guardian representative authority',array('grant_id','version','reason_code'));self::form('supersede_guardian_authority','Supersede guardian representative authority',array('grant_id','version','wordpress_user_id','verification_basis','evidence_channel','evidence_at','effective_until (optional)','reason_code'));}self::form('assess_acceptance_eligibility','Read acceptance eligibility (informational only)',array('booking_request_id','wordpress_user_id'));foreach(array('booking_request_identity_resolution_events'=>'Identity resolution history','student_acceptance_capacity_classifications'=>'Capacity classifications','student_principal_links'=>'Student principal links','student_acceptance_authority_grants'=>'Guardian representative grants')as$table=>$title)self::table($title,$repo->rows($table));echo '</div>';}
    private static function text(array $post,string $key):string{return sanitize_text_field((string)($post[$key]??''));}
    private static function optional(array $post,string $key):?string{$value=self::text($post,$key);return $value===''?null:$value;}
    private static function form(string $action,string $title,array $fields):void{echo '<h2>'.esc_html($title).'</h2><form method="post">';wp_nonce_field('dzn_platform_'.$action);echo '<input type="hidden" name="dzn_action" value="'.esc_attr($action).'">';foreach($fields as$field){$name=strtok($field,' ');echo '<p><label>'.esc_html($field).'<br><input class="regular-text" name="'.esc_attr($name).'"></label></p>';}submit_button('Save');echo '</form>';}
    private static function table(string $title,array $rows):void{echo '<h3>'.esc_html($title).'</h3>';if(!$rows){echo '<p>No records.</p>';return;}$fields=array_keys(get_object_vars($rows[0]));echo '<table class="widefat striped"><thead><tr>';foreach($fields as$field)echo '<th>'.esc_html($field).'</th>';echo '</tr></thead><tbody>';foreach($rows as$row){echo '<tr>';foreach($fields as$field)echo '<td>'.esc_html((string)($row->$field??'')).'</td>';echo '</tr>';}echo '</tbody></table>';}
    private static function messages():void{if(isset($_GET['dzn_notice']))echo '<div class="notice '.esc_attr((($_GET['dzn_error']??'')==='1'?'notice-error':'notice-success')).'"><p>'.esc_html(sanitize_text_field(wp_unslash($_GET['dzn_notice']))).'</p></div>';}
    private static function redirect(string $notice,bool $error=false):never{$url=add_query_arg(array('page'=>'dzn-student-identity-authority','dzn_notice'=>$notice,'dzn_error'=>$error?'1':'0'),admin_url('admin.php'));nocache_headers();if(wp_safe_redirect($url))exit;wp_die(esc_html($notice),'Delnavazan',array('response'=>$error?500:200));}
}
